UDim2.fromScale.example:
local frame = Instance.new("Frame")
frame.Size = UDim2.fromScale(0.5, 0.25) -- half as wide, a quarter as tall as the parent
print(frame.Size) --> {0.5, 0}, {0.25, 0}

UDim2.fromOffset.example:
local icon = Instance.new("ImageLabel")
icon.Size = UDim2.fromOffset(32, 32) -- always 32 x 32 pixels
print(icon.Size) --> {0, 32}, {0, 32}
